{"results": [{"id": "hp_doc_de04784861da40ffe9488b030483521dce8e2964f24e0671838e83a9e7d4d66e", "title": "Helmut Käser", "text": "Helmut Käser (14 November 1912 – 11 May 1994) served as the General Secretary of international governing body of association football FIFA, from April 1960 to June 1981. Käser served as general secretary under three presidents of FIFA, the Englishmen Arthur Drewry (1955–1961) and Stanley Rous (1961–1974) and from 1974 until 1980 under the Brazilian João Havelange.", "score": 25.1581}, {"id": "hp_doc_34f3b17363fb4c541cefc9f1a9f9156eec70b3b86fa2a2389ae4aea09d82486b", "title": "Stanley Rous", "text": "Sir Stanley Ford Rous, CBE (25 April 1895 – 18 July 1986) was the 6th President of FIFA, serving from 1961 to 1974. He also served as secretary of the Football Association from 1934 to 1962 and was an international referee.", "score": 19.4547}, {"id": "hp_doc_647a6b037d2a6a46508752d8cce3efaf18a4de81866f7e13b3f1c3c1448723c4", "title": "1934 FA Cup Final", "text": "The 1934 FA Cup Final was won by Manchester City in a 2–1 win over Portsmouth. The match is most remembered for a young Frank Swift's heroics in goal and the predictions of City forward Fred Tilson. The match was also refereed by future FIFA president Stanley Rous, in his penultimate game as an official.", "score": 13.373}], "remaining_searches": 2}
